	RotateInPlaceState.bUpdatedThisFrame = false;
	TurnInPlaceState.bUpdatedThisFrame = false;

	RefreshLayering();
	RefreshPose();
	RefreshView(DeltaTime);
	RefreshFeet(DeltaTime);
	RefreshTransitions();
}

